// План specs/android-app.md 1.5 (кейс .qa/tests/android-app/offline/OF-03). Pre-Prod, preprod-ttp (TTP Test Locks), EN.
// Лид НЕ сохраняется: Create Lead нажимается только без сети, после проверки — уход со страницы (удалить лид в UI нельзя).
// Если сохранение вдруг прошло (офлайн не сработал) — тест падает, лид «QA-AUTO offline lead …» удалить вручную.
import { test, expect } from '../../fixtures';
import { OFFLINE_TITLE, ROLE, TEST_PHONE, goOffline, offlineSaveMessage, pp, setEnglish, stamp, watchDialogs } from './offline-helpers';

test.describe('Офлайн — сохранение без сети (#6f8ef9)', () => {
  test('Create Lead offline shows an in-app "Nothing was saved" message and keeps the data #6f8ef9 @android', async ({ asUser }) => {
    const page = await asUser(ROLE);
    const name = `QA-AUTO offline lead #6f8ef9 ${stamp()}`;
    const dialogs = watchDialogs(page);
    try {
      await setEnglish(page);
      await page.goto(pp('/CreateLead'));
      const save = page.getByRole('button', { name: 'Create Lead' });
      await expect(save).toBeVisible({ timeout: 30_000 });
      const client = page.getByPlaceholder('Search clients...').first();
      const phone = page.getByPlaceholder('(234) 567-8900').first();
      await client.fill(name);
      await client.press('Escape');
      await phone.fill(TEST_PHONE);

      await goOffline(page);
      await save.click();

      // коммент программиста — формы клиент, лид…: сообщение внутри приложения, данные остаются
      await expect(offlineSaveMessage(page)).toBeVisible();
      await expect(page.getByText(OFFLINE_TITLE).filter({ visible: true }).first()).toBeVisible();
      expect(dialogs, 'системного окна быть не должно').toEqual([]);
      await expect(client).toHaveValue(name);
      await expect(phone).not.toHaveValue('');
      await expect(page).toHaveURL(/\/CreateLead/);
    } finally {
      await page.context().setOffline(false);
      if (!page.isClosed()) await page.goto(pp('/Leads')).catch(() => {});
    }
  });
});
